"use strict";

const http = require("http");

exports.read = function read(url) {
  return new Promise((resolve, reject) => {
    const req = http.get(url, { timeout: 1000 }, (res) => {
      const chunks = [];
      let ended = false;
      res.setEncoding("utf8");
      res.on("data", (chunk) => chunks.push(chunk));
      res.on("end", () => {
        ended = true;
        const lines = chunks.join("").trim().split(/\n+/).join(",");
        resolve([
          "httpnpm.incoming-stream=" + res.statusCode,
          lines,
          "ended=" + ended,
        ].join("|"));
      });
      res.on("error", reject);
    });
    req.on("error", reject);
  });
};
